/* Organic branch geometry, depth projection, wind and spring-driven leaves. */
(()=>{
const canvas=document.getElementById('spiritTree');if(!canvas)return;const ctx=canvas.getContext('2d'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let seed=71;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}const branches=[],leaves=[],roots=[];
function branch(origin,dir,length,depth,width){const points=[origin];let p=origin;for(let j=1;j<=7;j++){const q=j/7;p={x:origin.x+dir.x*length*q+Math.sin(q*Math.PI)*dir.z*.11,y:origin.y+dir.y*length*q,z:origin.z+dir.z*length*q+Math.sin(q*Math.PI)*.045};points.push(p)}branches.push({points,width,phase:random()*6.28});if(depth===0){for(let i=0;i<16;i++){const a=random()*6.28,r=Math.pow(random(),.5)*.21;leaves.push({x:p.x+Math.cos(a)*r,y:p.y+(random()-.3)*.27,z:p.z+Math.sin(a)*r,ox:0,oy:0,vx:0,vy:0,phase:random()*6.28,size:.012+random()*.015,warm:random()>.77})}return}
const count=depth>3?3:2;for(let k=0;k<count;k++){const a=random()*.8+k/count*6.28+depth*1.7,spread=depth>3?.55:.73,dx=dir.x*.45+Math.cos(a)*spread,dy=.5+random()*.34,dz=dir.z*.45+Math.sin(a)*spread,n=Math.hypot(dx,dy,dz);branch(p,{x:dx/n,y:dy/n,z:dz/n},length*(.64+random()*.12),depth-1,width*.59)}}
branch({x:0,y:-1.25,z:0},{x:.035,y:1,z:.02},.94,5,.075);
for(let i=0;i<17;i++){const a=i/17*Math.PI*2;roots.push(Array.from({length:16},(_,j)=>{const t=j/15;return{x:Math.cos(a+t*.45)*t*.85,y:-1.25-.2*Math.sin(t*Math.PI*.7),z:Math.sin(a+t*.45)*t*.85}}))}
const motes=Array.from({length:70},()=>({x:(random()-.5)*3.6,y:(random()-.5)*3.5,z:(random()-.5)*2.7,phase:random()*6.28}));let w=0,h=0,scale=1,yaw=.3,pitch=-.09,velocity=0,dragging=false,lastX=0,lastY=0,moved=0,pointer={x:-1e5,y:-1e5},time=0,last=0,raf=0,visible=false,pulses=[];
function resizeTree(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);scale=Math.min(w*.3,h*.255);queue()}
function project(p,wind=true){const sway=wind?Math.max(0,p.y+1.25)*Math.sin(time*.65+p.y*.9+p.z)*.026:0,x=p.x+sway,z=p.z,cy=Math.cos(yaw),sy=Math.sin(yaw),xx=x*cy+z*sy,zz=-x*sy+z*cy,yy=p.y*Math.cos(pitch)-zz*Math.sin(pitch),depth=p.y*Math.sin(pitch)+zz*Math.cos(pitch),persp=5/(5+depth);return{x:w*.5+xx*scale*persp,y:h*.52-yy*scale*persp,z:depth,p:persp}}
function pulse(){pulses.push({age:0});if(pulses.length>4)pulses.shift();queue()}
function strokePath(points,width,alpha,warm=false){const projected=points.map(p=>project(p));ctx.beginPath();projected.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineWidth=Math.max(.35,width*scale);ctx.strokeStyle=warm?`rgba(213,191,151,${alpha})`:`rgba(158,190,217,${alpha})`;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke()}
function frame(now){raf=0;if(!visible)return;const dt=Math.min(.035,(now-(last||now-16))/1000);last=now;if(!reduce)time+=dt;
if(!dragging){yaw+=velocity*dt+(reduce?0:dt*.032);velocity*=Math.exp(-3*dt)}pulses=pulses.filter(p=>(p.age+=dt)<3.3);ctx.clearRect(0,0,w,h);
const halo=ctx.createRadialGradient(w*.5,h*.49,0,w*.5,h*.49,scale*1.8);halo.addColorStop(0,'#8baed012');halo.addColorStop(1,'#8baed000');ctx.fillStyle=halo;ctx.fillRect(0,0,w,h);
roots.forEach(p=>strokePath(p,.002,.25,true));
branches.map(b=>({b,z:project(b.points.at(-1)).z})).sort((a,b)=>b.z-a.z).forEach(({b,z})=>{const p=b.points.at(-1),energy=pulses.reduce((v,e)=>v+Math.exp(-Math.pow((p.y+1.25-e.age*1.5)*3.5,2)),0);strokePath(b.points,b.width,Math.min(.8,.26+(1-z*.2)*.19+energy*.3),b.width>.016);if(energy>.15)strokePath(b.points,b.width*.2,Math.min(.9,energy*.6),true)});
const projected=[];for(const leaf of leaves){const p=project(leaf),dx=p.x+leaf.ox-pointer.x,dy=p.y+leaf.oy-pointer.y,d=Math.hypot(dx,dy);if(!reduce&&d<100&&d>1){const force=(1-d/100)*150;leaf.vx+=dx/d*force*dt;leaf.vy+=dy/d*force*dt}leaf.vx+=(-leaf.ox*9-leaf.vx*4.3)*dt;leaf.vy+=(-leaf.oy*9-leaf.vy*4.3)*dt;leaf.ox+=leaf.vx*dt;leaf.oy+=leaf.vy*dt;projected.push({leaf,p})}
projected.sort((a,b)=>b.p.z-a.p.z);for(const {leaf,p} of projected){const energy=pulses.reduce((v,e)=>v+Math.exp(-Math.pow((leaf.y+1.25-e.age*1.5)*3.8,2)),0),breath=1+Math.sin(time*1.2+leaf.phase)*.12,flutter=Math.sin(time*.9+leaf.phase)*.7,r=leaf.size*scale*p.p*breath,alpha=Math.min(.92,.32+(1.3-p.z)*.19+energy*.4);ctx.save();ctx.translate(p.x+leaf.ox,p.y+leaf.oy);ctx.rotate(leaf.phase+flutter);ctx.fillStyle=leaf.warm?`rgba(218,200,156,${alpha})`:`rgba(161,195,217,${alpha})`;ctx.beginPath();ctx.ellipse(0,0,r,r*(.27+Math.abs(Math.sin(leaf.phase+time*.4))*.25),0,0,Math.PI*2);ctx.fill();if(energy>.1){ctx.fillStyle=`rgba(218,228,243,${Math.min(.12,energy*.1)})`;ctx.beginPath();ctx.arc(0,0,r*3,0,Math.PI*2);ctx.fill()}ctx.restore()}
for(const m of motes){const p=project({x:m.x+Math.sin(time*.2+m.phase)*.12,y:m.y+Math.sin(time*.3+m.phase)*.18,z:m.z}),a=.16+(Math.sin(time+m.phase)+1)*.14;ctx.fillStyle=`rgba(207,212,205,${a})`;ctx.beginPath();ctx.arc(p.x,p.y,.7*p.p,0,Math.PI*2);ctx.fill()}
if(!reduce||pulses.length||Math.abs(velocity)>.001)queue()}
function queue(){if(!raf)raf=requestAnimationFrame(frame)}
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;moved=0;canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging')});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer={x:e.clientX-r.left,y:e.clientY-r.top};if(dragging){const dx=e.clientX-lastX,dy=e.clientY-lastY;moved+=Math.abs(dx)+Math.abs(dy);yaw+=dx*.006;pitch=Math.max(-.5,Math.min(.5,pitch+dy*.002));velocity=dx*.06;lastX=e.clientX;lastY=e.clientY}queue()});function release(){dragging=false;canvas.classList.remove('dragging')}canvas.addEventListener('pointerup',()=>{release();if(moved<9)pulse()});canvas.addEventListener('pointercancel',release);canvas.addEventListener('pointerleave',()=>{pointer={x:-1e5,y:-1e5}});canvas.addEventListener('keydown',e=>{if([' ','Enter','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key===' '||e.key==='Enter')pulse();else if(e.key==='ArrowLeft')yaw-=.15;else if(e.key==='ArrowRight')yaw+=.15;else pitch=Math.max(-.5,Math.min(.5,pitch+(e.key==='ArrowUp'?.08:-.08)));queue()}});
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;last=0;if(visible)queue()},{rootMargin:'150px'}).observe(canvas);addEventListener('resize',resizeTree);resizeTree();
})();
